+    }
+  }
+
+  function moveInput() {
+    let x = (input.right ? 1 : 0) - (input.left ? 1 : 0);
+    let y = (input.down ? 1 : 0) - (input.up ? 1 : 0);
+    if (Math.abs(input.stickX) + Math.abs(input.stickY) > 0.01) { x = input.stickX; y = input.stickY; }
