103:   function addMesh(parent, geometry, material, position, options = {}) {
104:     const mesh = new THREE.Mesh(geometry, material);
105:     mesh.position.copy(position);
106:     mesh.castShadow = options.castShadow ?? true;
107:     mesh.receiveShadow = options.receiveShadow ?? true;
108:     if (options.scale) mesh.scale.set(...options.scale);
109:     if (options.rotation) mesh.rotation.set(...options.rotation);
110:     parent.add(mesh);
111:     return mesh;
112:   }
