119:       const floor = addMesh(worldGroup, floorGeo, mat(REGIONS[r].ground), center, { rotation: [-Math.PI / 2, 0, Math.PI / 4], castShadow: false });
120:       floor.receiveShadow = true;
121:       const count = 9 * 6;
122:       const tiles = new THREE.InstancedMesh(tileGeo, mat(REGIONS[r].tile), count);
123:       let i = 0;
124:       for (let tx = 0; tx < 9; tx++) for (let ty = 0; ty < 6; ty++) {
125:         const x = r * REGION + (tx + 0.5) * 80;
126:         const y = (ty + 0.5) * (MAP_H / 6);
127:         temp.position.copy(worldAt(x, y, -0.055 + random01(x + y) * 0.008));
128:         temp.rotation.set(0, Math.PI / 4, 0);
