132:         const color = new THREE.Color(random01(x * 7 + y * 3) > 0.83 ? REGIONS[r].accent : REGIONS[r].tile);
133:         color.multiplyScalar(0.88 + random01(x + y * 11) * 0.24);
134:         tiles.setColorAt(i++, color);
135:       }
136:       tiles.instanceMatrix.needsUpdate = true;
137:       if (tiles.instanceColor) tiles.instanceColor.needsUpdate = true;
