150:   function buildTreesAndRocks() {
151:     for (let x = 95; x < WORLD; x += 200) {
152:       for (const y of [28, MAP_H - 28]) {
153:         const region = regionAt(x), g = new THREE.Group();
154:         const p = worldAt(x, y);
155:         g.position.set(p.x, 0, p.z);
156:         g.rotation.y = Math.PI / 4;
157:         const s = 0.82 + random01(x + y) * 0.48;
158:         addMesh(g, shared.trunk, mats.bark, v3(0, 0.66 * s, 0), { scale: [s, s, s] });
159:         const leafMat = region === 1 ? mats.snow : mat(REGIONS[region].leaf);
160:         for (let layer = 0; layer < 3; layer++) {
161:           addMesh(g, shared.foliage, leafMat, v3(0, (1.25 + layer * 0.5) * s, 0), { scale: [s * (1.15 - layer * 0.12), s, s * (1.15 - layer * 0.12)] });
162:         }
163:         worldGroup.add(g);
164:         colliders.push({ x, y, r: 22 * s });
165:       }
166:     }
167:     for (let i = 0; i < 34; i++) {
168:       const region = i % REGIONS.length;
169:       const x = region * REGION + 80 + random01(i + 100) * (REGION - 160);
170:       const y = 55 + random01(i + 700) * (MAP_H - 110);
171:       if (Math.abs(y - MAP_H / 2) < 70) continue;
172:       const p = worldAt(x, y, 0.18);
173:       const rock = addMesh(worldGroup, shared.rock, mat(i % 3 ? 0x68706a : 0x817c70), p, { scale: [0.55 + random01(i) * 0.6, 0.35 + random01(i + 2) * 0.35, 0.48 + random01(i + 3) * 0.5], rotation: [random01(i + 4), random01(i + 5), random01(i + 6)] });
174:       rock.castShadow = true;
