178:     for (let i = 0; i < WORLD / 105; i++) {
179:       for (const y of [8, MAP_H - 8]) {
180:         const x = 52 + i * 105;
181:         const p = worldAt(x, y, 0.16);
182:         addMesh(worldGroup, shared.rock, mats.rock, p, { scale: [0.52, 0.3, 0.48], rotation: [0.1, random01(i + y) * 2, 0.2] });
