373:   const particlePositions = new Float32Array(360 * 3);
374:   const particleColors = new Float32Array(360 * 3);
375:   const particleGeometry = new THREE.BufferGeometry();
376:   particleGeometry.setAttribute('position', new THREE.BufferAttribute(particlePositions, 3));
377:   particleGeometry.setAttribute('color', new THREE.BufferAttribute(particleColors, 3));
378:   const particleMaterial = new THREE.PointsMaterial({ size: 0.15, vertexColors: true, transparent: true, opacity: 0.9, depthWrite: false, sizeAttenuation: true });
379:   const particleSystem = new THREE.Points(particleGeometry, particleMaterial);
380:   particleSystem.frustumCulled = false;
381:   scene.add(particleSystem);
