383:   function updateParticles(dt) {
384:     for (const particle of particles) {
385:       particle.x += particle.vx * dt;
386:       particle.y += particle.vy * dt;
387:       particle.z += particle.vz * dt;
388:       particle.vy += 190 * dt;
389:       particle.life -= dt;
390:     }
391:     particles = particles.filter((particle) => particle.life > 0);
392:     const count = Math.min(particles.length, 360);
393:     for (let i = 0; i < count; i++) {
394:       const p = particles[i], world = worldAt(p.x, p.y, Math.max(0.06, p.z));
395:       particlePositions[i * 3] = world.x;
396:       particlePositions[i * 3 + 1] = world.y;
397:       particlePositions[i * 3 + 2] = world.z;
398:       const fade = Math.min(1, p.life / 0.2);
399:       particleColors[i * 3] = p.color.r * fade;
400:       particleColors[i * 3 + 1] = p.color.g * fade;
401:       particleColors[i * 3 + 2] = p.color.b * fade;
402:     }
403:     particleGeometry.setDrawRange(0, count);
404:     particleGeometry.attributes.position.needsUpdate = true;
405:     particleGeometry.attributes.color.needsUpdate = true;
