374:   const particlePositions = new Float32Array(360 * 3);
375:   const particleColors = new Float32Array(360 * 3);
376:   const particleGeometry = new THREE.BufferGeometry();
377:   particleGeometry.setAttribute('position', new THREE.BufferAttribute(particlePositions, 3));
378:   particleGeometry.setAttribute('color', new THREE.BufferAttribute(particleColors, 3));
379:   const particleMaterial = new THREE.PointsMaterial({ size: 0.15, vertexColors: true, transparent: true, opacity: 0.9, depthWrite: false, sizeAttenuation: true });
380:   const particleSystem = new THREE.Points(particleGeometry, particleMaterial);
381:   particleSystem.frustumCulled = false;
382:   scene.add(particleSystem);
