384:   function updateParticles(dt) {
385:     for (const particle of particles) {
386:       particle.x += particle.vx * dt;
387:       particle.y += particle.vy * dt;
388:       particle.z += particle.vz * dt;
389:       particle.vy += 190 * dt;
390:       particle.life -= dt;
391:     }
392:     particles = particles.filter((particle) => particle.life > 0);
393:     const count = Math.min(particles.length, 360);
394:     for (let i = 0; i < count; i++) {
395:       const p = particles[i], world = worldAt(p.x, p.y, Math.max(0.06, p.z));
396:       particlePositions[i * 3] = world.x;
397:       particlePositions[i * 3 + 1] = world.y;
398:       particlePositions[i * 3 + 2] = world.z;
399:       const fade = Math.min(1, p.life / 0.2);
400:       particleColors[i * 3] = p.color.r * fade;
401:       particleColors[i * 3 + 1] = p.color.g * fade;
402:       particleColors[i * 3 + 2] = p.color.b * fade;
403:     }
404:     particleGeometry.setDrawRange(0, count);
405:     particleGeometry.attributes.position.needsUpdate = true;
406:     particleGeometry.attributes.color.needsUpdate = true;
407:   }
