409:   function blocked(x, y, radius = 12) {
410:     if (y < 14 || y > MAP_H - 14 || x < 5 || x > WORLD - 5) return true;
411:     for (const obstacle of colliders) {
412:       const dx = x - obstacle.x, dy = y - obstacle.y;
413:       const reach = radius + obstacle.r;
414:       if (dx * dx + dy * dy < reach * reach) return true;
415:     }
416:     for (const gate of gates) {
417:       if (!gate.open && Math.abs(x - gate.x) < radius + 16 && Math.abs(y - gate.y) < 72) return true;
418:     }
419:     return false;
420:   }
