422:   function moveWithCollision(actor, dx, dy, radius = 12) {
423:     const oldX = actor.x, oldY = actor.y;
424:     if (!blocked(oldX + dx, oldY, radius)) actor.x += dx;
425:     else actor.vx = 0;
426:     if (!blocked(actor.x, oldY + dy, radius)) actor.y += dy;
427:     else actor.vy = 0;
428:     if (actor.x === oldX && actor.y === oldY) {
429:       actor.vx *= 0.15;
430:       actor.vy *= 0.15;
431:     }
432:   }
