449:   function moveInput() {
450:     let x = (input.right ? 1 : 0) - (input.left ? 1 : 0);
451:     let y = (input.down ? 1 : 0) - (input.up ? 1 : 0);
452:     if (Math.abs(input.stickX) + Math.abs(input.stickY) > 0.01) { x = input.stickX; y = input.stickY; }
453:     const length = Math.hypot(x, y);
454:     if (length > 1) { x /= length; y /= length; }
455:     return { x, y };
