473:   function attackTargets() {
474:     if (hero.attack <= 0) return;
475:     const strike = (target, range) => {
476:       const dx = target.x - hero.x, dy = target.y - hero.y;
477:       const distance = Math.hypot(dx, dy) || 1;
478:       return distance < range && (dx * hero.faceX + dy * hero.faceY) / distance > 0.28;
479:     };
480:     for (const enemy of enemies) {
481:       if (!enemy.alive || !strike(enemy, 65)) continue;
482:       enemy.hp--;
483:       enemy.x += hero.faceX * 17; enemy.y += hero.faceY * 17;
484:       burst(enemy.x, enemy.y, 0xa8da8e, 9);
485:       hero.attack = 0.06;
486:       if (enemy.hp <= 0) {
487:         enemy.alive = false; enemy.model.root.visible = false;
488:         burst(enemy.x, enemy.y, 0x8bd17d, 15); showToast('Forest slime defeated');
489:       }
490:       return;
491:     }
492:     const region = regionAt(hero.x), boss = bosses[region];
493:     if (boss?.alive && strike(boss, 82) && boss.hitCd <= 0) {
494:       boss.hp--; boss.hitCd = 0.42; hero.attack = 0.06;
495:       boss.healthMesh.scale.x = 1.29 * (boss.hp / boss.maxHp);
496:       boss.healthMesh.position.x = -0.66 + (boss.healthMesh.scale.x / 2);
497:       burst(boss.x, boss.y, 0xffd57a, 14);
498:       if (boss.hp <= 0) {
499:         boss.alive = false; boss.model.root.visible = false; keysFound++;
500:         gates[region].open = true;
501:         const portalMaterial = gates[region].portal.material;
502:         portalMaterial.color.setHex(0xffcf72); portalMaterial.emissive.setHex(0x8e5719); portalMaterial.opacity = 0.55;
503:         showToast(`${REGIONS[region].name} key found!`); updateHUD(); updateQuest();
504:         burst(boss.x, boss.y, 0xffe7a0, 28);
505:       } else showToast(`${REGIONS[region].boss} · ${boss.hp} strikes left`);
506:       return;
507:     }
508:   }
