510:   function update(dt) {
511:     elapsed += dt;
512:     if (toastTimer > 0 && (toastTimer -= dt) <= 0) ui.toast.classList.remove('show');
513:     if (screen !== 'playing') { updateParticles(dt); return; }
514:     const direction = moveInput();
515:     const speed = 190;
516:     const response = direction.x || direction.y ? 10.5 : 8.5;
517:     hero.vx += (direction.x * speed - hero.vx) * Math.min(1, dt * response);
518:     hero.vy += (direction.y * speed - hero.vy) * Math.min(1, dt * response);
519:     if (Math.abs(direction.x) < 0.01) hero.vx *= Math.pow(0.08, dt);
520:     if (Math.abs(direction.y) < 0.01) hero.vy *= Math.pow(0.08, dt);
521:     moveWithCollision(hero, hero.vx * dt, hero.vy * dt, 12);
522:     if (direction.x || direction.y) faceHero(direction.x, direction.y);
523:     if (hero.invuln > 0) hero.invuln = Math.max(0, hero.invuln - dt);
524:     if (hero.attack > 0) hero.attack = Math.max(0, hero.attack - dt);
525:     if (hero.attackCd > 0) hero.attackCd = Math.max(0, hero.attackCd - dt);
526:     if (input.attack && hero.attackCd <= 0) startAttack();
527:     hero.model.swordPivot.rotation.x = hero.attack > 0 ? -0.45 - Math.sin((1 - hero.attack / 0.34) * Math.PI) * 1.6 : 0;
528:     hero.model.root.position.y = Math.hypot(hero.vx, hero.vy) > 8 ? Math.abs(Math.sin(elapsed * 12)) * 0.07 : 0;
529:     hero.model.legs[0].rotation.x = Math.sin(elapsed * 11) * Math.min(0.5, Math.hypot(hero.vx, hero.vy) / 300);
530:     hero.model.legs[1].rotation.x = -hero.model.legs[0].rotation.x;
531:     placeHero();
532: 
533:     for (const coin of coins) {
534:       if (coin.taken) continue;
535:       coin.group.position.y = 0.93 + Math.sin(elapsed * 3.2 + coin.phase) * 0.11;
536:       coin.group.rotation.y = elapsed * 1.7;
537:       if (Math.hypot(hero.x - coin.x, hero.y - coin.y) < 28) {
538:         coin.taken = true; coin.group.visible = false; burst(coin.x, coin.y, 0xffd36f, 10); updateHUD(); showToast('A little treasure for the road');
539:       }
540:     }
541:     for (const cp of checkpoints) {
542:       cp.flame.rotation.y = elapsed * 1.6;
543:       cp.flame.scale.setScalar(0.85 + Math.sin(elapsed * 5) * 0.12);
544:       if (!cp.active && Math.hypot(hero.x - cp.x, hero.y - cp.y) < 30) {
545:         checkpoints.forEach((point) => { point.active = false; }); cp.active = true;
546:         hero.checkpoint = { x: cp.x, y: cp.y }; showToast('Campfire found · progress saved'); burst(cp.x, cp.y, 0xffd47d, 14);
547:       }
548:     }
549: 
550:     for (const enemy of enemies) {
551:       if (!enemy.alive) continue;
552:       let dx = hero.x - enemy.x, dy = hero.y - enemy.y, distance = Math.hypot(dx, dy) || 1;
553:       if (distance < 175) { enemy.vx = (enemy.vx || 0) + (dx / distance * 48 - (enemy.vx || 0)) * Math.min(1, dt * 3); enemy.vy = (enemy.vy || 0) + (dy / distance * 48 - (enemy.vy || 0)) * Math.min(1, dt * 3); }
554:       else { enemy.vx = (enemy.homeX + Math.sin(elapsed * 0.6 + enemy.phase) * 24 - enemy.x) * 0.8; enemy.vy = (enemy.homeY + Math.cos(elapsed * 0.5 + enemy.phase) * 20 - enemy.y) * 0.8; }
555:       moveWithCollision(enemy, enemy.vx * dt, enemy.vy * dt, 14);
