412:       const max = Math.max(1, rect.width * 0.5 - stickKnob.offsetWidth * 0.5 - 4);
413:       let dx = event.clientX - (rect.left + rect.width * 0.5);
414:       let dy = event.clientY - (rect.top + rect.height * 0.5);
415:       const distance = Math.hypot(dx, dy);
416:       if (distance > max) { dx *= max / distance; dy *= max / distance; }
417:       let x = dx / max, y = dy / max;
418:       const magnitude = Math.hypot(x, y);
419:       if (magnitude < 0.12) x = y = 0;
420:       else if (magnitude > 1) { x /= magnitude; y /= magnitude; }
421:       input.stickX = x;
422:       input.stickY = y;
423:       stickKnob.style.transform = `translate(${dx}px, ${dy}px)`;
