446:   function burst(x, y, color, count = 10) {
447:     for (let i = 0; i < count; i++) {
448:       particles.push({ x, y, z: 0.3 + Math.random() * 1.15, vx: (Math.random() - 0.5) * 90, vy: -30 - Math.random() * 95, vz: 0.45 + Math.random() * 0.6, life: 0.35 + Math.random() * 0.55, maxLife: 0.9, color: new THREE.Color(color) });
449:     }
450:   }
