452:   const particlePositions = new Float32Array(360 * 3);
453:   const particleColors = new Float32Array(360 * 3);
454:   const particleGeometry = new THREE.BufferGeometry();
455:   particleGeometry.setAttribute('position', new THREE.BufferAttribute(particlePositions, 3));
456:   particleGeometry.setAttribute('color', new THREE.BufferAttribute(particleColors, 3));
457:   const particleMaterial = new THREE.PointsMaterial({ size: 0.15, vertexColors: true, transparent: true, opacity: 0.9, depthWrite: false, sizeAttenuation: true });
458:   const particleSystem = new THREE.Points(particleGeometry, particleMaterial);
459:   particleSystem.frustumCulled = false;
460:   scene.add(particleSystem);
