462:   function updateParticles(dt) {
463:     for (const particle of particles) {
464:       particle.x += particle.vx * dt;
465:       particle.y += particle.vy * dt;
466:       particle.z += particle.vz * dt;
467:       particle.vy += 190 * dt;
468:       particle.life -= dt;
469:     }
470:     particles = particles.filter((particle) => particle.life > 0);
471:     const count = Math.min(particles.length, 360);
472:     for (let i = 0; i < count; i++) {
473:       const p = particles[i], world = worldAt(p.x, p.y, Math.max(0.06, p.z));
474:       particlePositions[i * 3] = world.x;
475:       particlePositions[i * 3 + 1] = world.y;
476:       particlePositions[i * 3 + 2] = world.z;
477:       const fade = Math.min(1, p.life / 0.2);
478:       particleColors[i * 3] = p.color.r * fade;
479:       particleColors[i * 3 + 1] = p.color.g * fade;
480:       particleColors[i * 3 + 2] = p.color.b * fade;
481:     }
482:     particleGeometry.setDrawRange(0, count);
483:     particleGeometry.attributes.position.needsUpdate = true;
484:     particleGeometry.attributes.color.needsUpdate = true;
485:   }
