487:   function blocked(x, y, radius = 12) {
488:     if (y < 14 || y > MAP_H - 14 || x < 5 || x > WORLD - 5) return true;
489:     for (const obstacle of colliders) {
490:       const dx = x - obstacle.x, dy = y - obstacle.y;
491:       const reach = radius + obstacle.r;
492:       if (dx * dx + dy * dy < reach * reach) return true;
493:     }
494:     for (const gate of gates) {
495:       if (!gate.open && Math.abs(x - gate.x) < radius + 16 && Math.abs(y - gate.y) < 72) return true;
496:     }
497:     return false;
498:   }
