500:   function moveWithCollision(actor, dx, dy, radius = 12) {
501:     const oldX = actor.x, oldY = actor.y;
502:     if (!blocked(oldX + dx, oldY, radius)) actor.x += dx;
503:     else actor.vx = 0;
504:     if (!blocked(actor.x, oldY + dy, radius)) actor.y += dy;
505:     else actor.vy = 0;
506:     if (actor.x === oldX && actor.y === oldY) {
507:       actor.vx *= 0.15;
508:       actor.vy *= 0.15;
509:     }
510:   }
