551:   function attackTargets() {
552:     if (hero.attack <= 0) return;
553:     const strike = (target, range) => {
554:       const dx = target.x - hero.x, dy = target.y - hero.y;
555:       const distance = Math.hypot(dx, dy) || 1;
556:       return distance < range && (dx * hero.faceX + dy * hero.faceY) / distance > 0.28;
557:     };
558:     for (const enemy of enemies) {
559:       if (!enemy.alive || !strike(enemy, 65)) continue;
560:       enemy.hp--;
561:       enemy.x += hero.faceX * 17; enemy.y += hero.faceY * 17;
562:       burst(enemy.x, enemy.y, 0xa8da8e, 9);
563:       hero.attack = 0.06;
564:       if (enemy.hp <= 0) {
