566:         burst(enemy.x, enemy.y, 0x8bd17d, 15); showToast('Forest slime defeated');
567:       }
568:       return;
569:     }
570:     const region = regionAt(hero.x), boss = bosses[region];
571:     if (boss?.alive && strike(boss, 82) && boss.hitCd <= 0) {
572:       boss.hp--; boss.hitCd = 0.42; hero.attack = 0.06;
573:       boss.healthMesh.scale.x = 1.29 * (boss.hp / boss.maxHp);
574:       boss.healthMesh.position.x = -0.66 + (boss.healthMesh.scale.x / 2);
575:       burst(boss.x, boss.y, 0xffd57a, 14);
576:       if (boss.hp <= 0) {
577:         boss.alive = false; boss.model.root.visible = false; keysFound++;
578:         gates[region].open = true;
579:         const portalMaterial = gates[region].portal.material;
580:         portalMaterial.color.setHex(0xffcf72); portalMaterial.emissive.setHex(0x8e5719); portalMaterial.opacity = 0.55;
581:         showToast(`${REGIONS[region].name} key found!`); updateHUD(); updateQuest();
582:         burst(boss.x, boss.y, 0xffe7a0, 28);
583:       } else showToast(`${REGIONS[region].boss} · ${boss.hp} strikes left`);
584:       return;
585:     }
