588:   function update(dt) {
589:     elapsed += dt;
590:     if (toastTimer > 0 && (toastTimer -= dt) <= 0) ui.toast.classList.remove('show');
591:     if (screen !== 'playing') { updateParticles(dt); return; }
592:     const direction = moveInput();
593:     const speed = 190;
594:     const response = direction.x || direction.y ? 10.5 : 8.5;
595:     hero.vx += (direction.x * speed - hero.vx) * Math.min(1, dt * response);
596:     hero.vy += (direction.y * speed - hero.vy) * Math.min(1, dt * response);
597:     if (Math.abs(direction.x) < 0.01) hero.vx *= Math.pow(0.08, dt);
598:     if (Math.abs(direction.y) < 0.01) hero.vy *= Math.pow(0.08, dt);
599:     moveWithCollision(hero, hero.vx * dt, hero.vy * dt, 12);
600:     if (direction.x || direction.y) faceHero(direction.x, direction.y);
601:     if (hero.invuln > 0) hero.invuln = Math.max(0, hero.invuln - dt);
602:     if (hero.attack > 0) hero.attack = Math.max(0, hero.attack - dt);
603:     if (hero.attackCd > 0) hero.attackCd = Math.max(0, hero.attackCd - dt);
604:     if (input.attack && hero.attackCd <= 0) startAttack();
605:     hero.model.swordPivot.rotation.x = hero.attack > 0 ? -0.45 - Math.sin((1 - hero.attack / 0.34) * Math.PI) * 1.6 : 0;
606:     hero.model.root.position.y = Math.hypot(hero.vx, hero.vy) > 8 ? Math.abs(Math.sin(elapsed * 12)) * 0.07 : 0;
607:     hero.model.legs[0].rotation.x = Math.sin(elapsed * 11) * Math.min(0.5, Math.hypot(hero.vx, hero.vy) / 300);
608:     hero.model.legs[1].rotation.x = -hero.model.legs[0].rotation.x;
609:     placeHero();
610: 
611:     for (const coin of coins) {
612:       if (coin.taken) continue;
